static boolean[] primeSieve(int limit) {

    boolean[] isPrime = new boolean[limit + 1];

    for (int number = 2; number < limit; number++) {
        isPrime[number] = true;
    }

    for (int currentPrime = 2; currentPrime < limit; currentPrime = nextPrime(isPrime, currentPrime)) {

        for (int multiple = currentPrime + currentPrime; multiple < limit; multiple += currentPrime) {

            if (multiple % currentPrime == 0) {
                isPrime[multiple] = false;
            }
        }
    }

    return isPrime;
}
