function is_above_ema()
{
    // Get the current candle's close price
    close_price = close[0]

    // Get the 50 EMA value
    ema_value = ema(close, ema_period)

    // Check if the close price is above the EMA
    if (close_price > ema_value)
        return true
    else
        return false
}

